-- Character.AI Files for Bankruptcy; the App Still Works but Could Shut Down After a Sale
-- Источник: https://blog.character.ai/an-update-on-character-ai/. Идемпотентно.

DELETE FROM news WHERE slug = 'character-ai-chapter-11-bankruptcy';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'en', 'business', $t$Business$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI Files for Bankruptcy; the App Still Works but Could Shut Down After a Sale$t$, $t$Character.AI filed for Chapter 11 bankruptcy in Delaware to sell its assets, with Disney as the first bidder at $20 million for a non-exclusive license to some of its technology. The app and paid subscriptions keep working for now, users can export their data, and the platform may close if no workable bid arrives.$t$, $t$<p><strong>Character.AI</strong>, the app for chatting with AI characters, filed for Chapter 11 bankruptcy in the Delaware bankruptcy court on October 12 to sell its assets. The first bidder is <strong>Disney</strong>, which offered $20 million for a non-exclusive license to some of Character.AI's technology. The sale is expected to finish by late November or early December.</p>
<h2>What happens to users</h2>
<p>The company says the platform remains up and running and all services are still available. Paid subscriptions stay active, and users can export their data. If no workable bid comes in, the platform will be shut down.</p>
<h2>What to do now</h2>
<p>If you have characters or long conversations you care about, export them now rather than waiting for the outcome of the sale. Character.AI's own update is the place to watch for changes to subscriptions and access.</p>
<h2>Why it matters</h2>
<p>Character.AI was one of the best-known consumer AI apps, with a large audience for roleplay and storytelling. Its bankruptcy is a reminder that conversations and creations stored in an AI app depend on the company behind it, and that keeping your own copies matters when choosing where to build.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'es', 'business', $t$Negocios$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI se declara en quiebra; la app sigue funcionando pero podría cerrar tras una venta$t$, $t$Character.AI se acogió al Capítulo 11 de bancarrota en Delaware para vender sus activos, con Disney como primer postor con 20 millones de dólares por una licencia no exclusiva de parte de su tecnología. La app y las suscripciones pagas siguen funcionando por ahora, los usuarios pueden exportar sus datos, y la plataforma podría cerrar si no llega una oferta viable.$t$, $t$<p><strong>Character.AI</strong>, la app para chatear con personajes de IA, se acogió al Capítulo 11 de bancarrota en el tribunal de quiebras de Delaware el 12 de octubre para vender sus activos. El primer postor es <strong>Disney</strong>, que ofreció 20 millones de dólares por una licencia no exclusiva de parte de la tecnología de Character.AI. Se espera que la venta concluya a fines de noviembre o principios de diciembre.</p>
<h2>Qué pasa con los usuarios</h2>
<p>La empresa afirma que la plataforma sigue activa y en funcionamiento y que todos los servicios continúan disponibles. Las suscripciones pagas siguen activas, y los usuarios pueden exportar sus datos. Si no llega ninguna oferta viable, la plataforma será cerrada.</p>
<h2>Qué hacer ahora</h2>
<p>Si tienes personajes o conversaciones largas que te importan, expórtalos ahora en lugar de esperar al resultado de la venta. La propia actualización de Character.AI es el lugar donde hay que estar atento a los cambios en las suscripciones y el acceso.</p>
<h2>Por qué importa</h2>
<p>Character.AI era una de las aplicaciones de IA de consumo más conocidas, con una gran audiencia para el roleplay y la narración de historias. Su quiebra es un recordatorio de que las conversaciones y creaciones almacenadas en una app de IA dependen de la empresa que está detrás, y de que conservar copias propias importa a la hora de elegir dónde construir.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'de', 'business', $t$Wirtschaft$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI meldet Insolvenz an; App läuft vorerst weiter, Abschaltung nach Verkauf möglich$t$, $t$Character.AI hat in Delaware ein Insolvenzverfahren nach Chapter 11 eingeleitet, um seine Vermögenswerte zu verkaufen. Disney ist mit einem Gebot von 20 Millionen Dollar für eine nicht-exklusive Lizenz an einem Teil der Technologie der erste Bieter. App und kostenpflichtige Abonnements funktionieren vorerst weiter, Nutzer können ihre Daten exportieren, und die Plattform könnte geschlossen werden, falls kein tragfähiges Angebot eingeht.$t$, $t$<p><strong>Character.AI</strong>, die App zum Chatten mit KI-Charakteren, hat am 12. Oktober beim Insolvenzgericht in Delaware ein Insolvenzverfahren nach Chapter 11 eingeleitet, um seine Vermögenswerte zu verkaufen. Erster Bieter ist <strong>Disney</strong>, das 20 Millionen Dollar für eine nicht-exklusive Lizenz an einem Teil der Technologie von Character.AI geboten hat. Der Verkauf soll bis Ende November oder Anfang Dezember abgeschlossen sein.</p>
<h2>Was mit Nutzern passiert</h2>
<p>Das Unternehmen erklärt, dass die Plattform weiterhin in Betrieb ist und alle Dienste verfügbar bleiben. Kostenpflichtige Abonnements bleiben aktiv, und Nutzer können ihre Daten exportieren. Sollte kein tragfähiges Angebot eingehen, wird die Plattform abgeschaltet.</p>
<h2>Was jetzt zu tun ist</h2>
<p>Wer Charaktere oder längere Unterhaltungen behalten möchte, sollte diese jetzt exportieren, anstatt das Ergebnis des Verkaufs abzuwarten. Die eigenen Mitteilungen von Character.AI sind die Quelle, die man im Blick behalten sollte, um Änderungen bei Abonnements und Zugang zu verfolgen.</p>
<h2>Warum es wichtig ist</h2>
<p>Character.AI war eine der bekanntesten KI-Apps für Verbraucher mit einem großen Publikum für Rollenspiele und Geschichtenerzählen. Die Insolvenz erinnert daran, dass Unterhaltungen und Inhalte, die in einer KI-App gespeichert sind, vom dahinterstehenden Unternehmen abhängen – und dass es wichtig ist, eigene Kopien zu behalten, wenn man entscheidet, worauf man aufbaut.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'ru', 'business', $t$Бизнес$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI подала заявление о банкротстве: приложение пока работает, но может закрыться после продажи$t$, $t$Character.AI подала заявление о банкротстве по главе 11 в суде штата Делавэр с целью продажи активов компании, а первым претендентом выступила Disney, предложившая $20 million за неэксклюзивную лицензию на часть технологий компании. Приложение и платные подписки пока работают, пользователи могут экспортировать свои данные, а платформа может закрыться, если не найдется подходящее предложение.$t$, $t$<p><strong>Character.AI</strong>, приложение для общения с ИИ-персонажами, подала заявление о банкротстве по главе 11 в суде по делам о банкротстве штата Делавэр 12 октября с целью продажи своих активов. Первый претендент — <strong>Disney</strong>, предложившая $20 million за неэксклюзивную лицензию на часть технологий Character.AI. Ожидается, что продажа завершится к концу ноября — началу декабря.</p>
<h2>Что будет с пользователями</h2>
<p>Компания заявляет, что платформа продолжает работать и все сервисы по-прежнему доступны. Платные подписки остаются активными, пользователи могут экспортировать свои данные. Если не поступит подходящее предложение, платформа будет закрыта.</p>
<h2>Что делать сейчас</h2>
<p>Если у вас есть персонажи или длинные беседы, которыми вы дорожите, экспортируйте их сейчас, не дожидаясь исхода продажи. Следите за обновлениями самой Character.AI — именно там будут публиковаться изменения, касающиеся подписок и доступа.</p>
<h2>Почему это важно</h2>
<p>Character.AI была одним из самых известных потребительских ИИ-приложений с большой аудиторией, увлеченной ролевыми играми и созданием историй. Её банкротство — напоминание о том, что беседы и материалы, сохраненные в ИИ-приложении, зависят от стоящей за ним компании, и что хранить собственные копии важно при выборе платформы для творчества.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'ua', 'business', $t$Бізнес$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI подав заяву про банкрутство: застосунок поки працює, але може закритися після продажу$t$, $t$Character.AI подав заяву про банкрутство за статтею 11 у суді Делавера для продажу своїх активів, і першим претендентом виступила компанія Disney, яка запропонувала $20 мільйонів за невиключну ліцензію на частину технологій компанії. Застосунок і платні підписки наразі продовжують працювати, користувачі можуть експортувати свої дані, а платформа може закритися, якщо не надійде прийнятна пропозиція.$t$, $t$<p><strong>Character.AI</strong>, застосунок для спілкування з ШІ-персонажами, 12 жовтня подав заяву про банкрутство за статтею 11 у суді з питань банкрутства Делавера з метою продажу своїх активів. Першим претендентом стала компанія <strong>Disney</strong>, яка запропонувала $20 мільйонів за невиключну ліцензію на частину технологій Character.AI. Очікується, що продаж завершиться наприкінці листопада або на початку грудня.</p>
<h2>Що буде з користувачами</h2>
<p>Компанія повідомляє, що платформа залишається доступною, і всі сервіси продовжують працювати. Платні підписки залишаються активними, а користувачі можуть експортувати свої дані. Якщо прийнятної пропозиції не надійде, платформу закриють.</p>
<h2>Що робити зараз</h2>
<p>Якщо у вас є персонажі чи довгі розмови, якими ви дорожите, експортуйте їх зараз, не чекаючи результатів продажу. За оновленнями щодо підписок і доступу варто стежити безпосередньо в офіційних повідомленнях Character.AI.</p>
<h2>Чому це важливо</h2>
<p>Character.AI був одним із найвідоміших споживчих ШІ-застосунків із великою аудиторією, що цікавилася рольовими іграми та створенням історій. Його банкрутство нагадує, що розмови та творчі напрацювання, збережені в ШІ-застосунку, залежать від компанії, яка стоїть за ним, і що зберігати власні копії важливо, обираючи, де будувати свій контент.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'he', 'business', $t$עסקים$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI מגישה בקשה לפשיטת רגל; האפליקציה עדיין פועלת אך עלולה להיסגר לאחר מכירה$t$, $t$Character.AI הגישה בקשה לפשיטת רגל לפי פרק 11 בבית המשפט בדלאוור כדי למכור את נכסיה, כאשר Disney היא המציעה הראשונה בסכום של 20 מיליון דולר עבור רישיון לא בלעדי לחלק מהטכנולוגיה שלה. האפליקציה והמנויים בתשלום ממשיכים לפעול בינתיים, המשתמשים יכולים לייצא את הנתונים שלהם, והפלטפורמה עלולה להיסגר אם לא תתקבל הצעה ישימה.$t$, $t$<p><strong>Character.AI</strong>, האפליקציה לשיחות עם דמויות מבוססות בינה מלאכותית, הגישה בקשה לפשיטת רגל לפי פרק 11 בבית המשפט לפשיטות רגל בדלאוור ב-12 באוקטובר, על מנת למכור את נכסיה. המציעה הראשונה היא <strong>Disney</strong>, שהציעה 20 מיליון דולר עבור רישיון לא בלעדי לחלק מהטכנולוגיה של Character.AI. המכירה צפויה להסתיים עד סוף נובמבר או תחילת דצמבר.</p>
<h2>מה קורה למשתמשים</h2>
<p>החברה מציינת שהפלטפורמה ממשיכה לפעול וכל השירותים עדיין זמינים. המנויים בתשלום נותרים פעילים, והמשתמשים יכולים לייצא את הנתונים שלהם. אם לא תתקבל הצעה ישימה, הפלטפורמה תיסגר.</p>
<h2>מה לעשות עכשיו</h2>
<p>אם יש לכם דמויות או שיחות ארוכות שחשובות לכם, מומלץ לייצא אותן כעת במקום להמתין לתוצאות המכירה. העדכונים הרשמיים של Character.AI הם המקום לעקוב אחרי שינויים במנויים ובגישה.</p>
<h2>למה זה חשוב</h2>
<p>Character.AI הייתה אחת מאפליקציות הבינה המלאכותית הצרכניות המוכרות ביותר, עם קהל גדול לתחומי משחק תפקידים וכתיבת סיפורים. פשיטת הרגל שלה מהווה תזכורת לכך שהשיחות והיצירות השמורות באפליקציית בינה מלאכותית תלויות בחברה שמאחוריה, ושחשיבות השמירה על עותקים אישיים משלכם עולה בעת הבחירה היכן לבנות.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'fr', 'business', $t$Business$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI se déclare en faillite ; l'application fonctionne encore mais pourrait fermer après une vente$t$, $t$Character.AI a déposé le bilan au titre du Chapter 11 dans le Delaware pour vendre ses actifs, Disney étant le premier enchérisseur avec une offre de 20 millions de dollars pour une licence non exclusive sur une partie de sa technologie. L'application et les abonnements payants continuent de fonctionner pour l'instant, les utilisateurs peuvent exporter leurs données, et la plateforme pourrait fermer si aucune offre viable n'est trouvée.$t$, $t$<p><strong>Character.AI</strong>, l'application permettant de discuter avec des personnages IA, a déposé le bilan au titre du Chapter 11 auprès du tribunal des faillites du Delaware le 12 octobre afin de vendre ses actifs. Le premier enchérisseur est <strong>Disney</strong>, qui a proposé 20 millions de dollars pour une licence non exclusive sur une partie de la technologie de Character.AI. La vente devrait aboutir d'ici fin novembre ou début décembre.</p>
<h2>Ce qui arrive aux utilisateurs</h2>
<p>L'entreprise indique que la plateforme reste en ligne et que tous les services demeurent disponibles. Les abonnements payants restent actifs, et les utilisateurs peuvent exporter leurs données. Si aucune offre viable n'est trouvée, la plateforme sera fermée.</p>
<h2>Que faire maintenant</h2>
<p>Si vous avez des personnages ou de longues conversations auxquels vous tenez, exportez-les dès maintenant plutôt que d'attendre l'issue de la vente. C'est la mise à jour de Character.AI elle-même qu'il faut surveiller pour tout changement concernant les abonnements et l'accès.</p>
<h2>Pourquoi c'est important</h2>
<p>Character.AI était l'une des applications d'IA grand public les plus connues, avec un large public pour le jeu de rôle et la création d'histoires. Sa faillite rappelle que les conversations et créations stockées dans une application d'IA dépendent de l'entreprise qui la gère, et qu'il importe de conserver ses propres copies lorsqu'on choisit où construire.</p>$t$, NULL, true);
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, source_url, date, title, summary, body, image_url, published)
VALUES ('character-ai-chapter-11-bankruptcy', 'pt', 'business', $t$Negócios$t$, '#f5a623', $t$Character.AI$t$, $t$https://blog.character.ai/an-update-on-character-ai/$t$, '2026-10-12', $t$Character.AI entra com pedido de falência; aplicativo ainda funciona, mas pode ser encerrado após venda$t$, $t$A Character.AI deu entrada em pedido de recuperação judicial (Chapter 11) em Delaware para vender seus ativos, com a Disney como primeira interessada, oferecendo US$ 20 milhões por uma licença não exclusiva de parte de sua tecnologia. O aplicativo e as assinaturas pagas continuam funcionando por enquanto, os usuários podem exportar seus dados, e a plataforma pode ser encerrada caso não surja uma proposta viável.$t$, $t$<p><strong>Character.AI</strong>, o aplicativo para conversar com personagens de IA, deu entrada em pedido de recuperação judicial (Chapter 11) no tribunal de falências de Delaware em 12 de outubro para vender seus ativos. A primeira interessada é a <strong>Disney</strong>, que ofereceu US$ 20 milhões por uma licença não exclusiva de parte da tecnologia da Character.AI. A venda deve ser concluída até o fim de novembro ou início de dezembro.</p>
<h2>O que acontece com os usuários</h2>
<p>A empresa afirma que a plataforma continua no ar e que todos os serviços seguem disponíveis. As assinaturas pagas permanecem ativas, e os usuários podem exportar seus dados. Caso não surja uma proposta viável, a plataforma será encerrada.</p>
<h2>O que fazer agora</h2>
<p>Se você tem personagens ou conversas longas que considera importantes, exporte-os agora, em vez de esperar pelo resultado da venda. As atualizações da própria Character.AI são o canal a acompanhar para mudanças nas assinaturas e no acesso.</p>
<h2>Por que isso importa</h2>
<p>A Character.AI era um dos aplicativos de IA para consumidores mais conhecidos, com um grande público voltado a roleplay e narrativas. Sua falência serve como lembrete de que as conversas e criações armazenadas em um aplicativo de IA dependem da empresa por trás dele, e de que manter cópias próprias é importante na hora de escolher onde construir.</p>$t$, NULL, true);
